// Fixed-length service cables; no rope solver, no persistent world-state traps.
export function setupTethers(g){g.tethers=(g.level.tethers||[]).map(t=>({...t,held:false,connected:false,last:null}));}
export function tetherAction(g,id){const t=g.tethers?.find(t=>t.id===id||t.socket===id);if(!t)return false;if(t.socket===id){if(t.held&&Math.hypot(g.player.x+14-t.toX,g.player.y+20-t.toY)<85&&(!t.printSite||g.printer.journey.sites[t.printSite].progress>=1)){t.connected=true;t.held=false;}}else if(!t.connected){t.held=!t.held;t.last={x:g.player.x,y:g.player.y};}return true;}
export function constrainTethers(g){for(const t of g.tethers||[]){if(!t.held)continue;const p=g.player;if(Math.hypot(p.x+14-t.x,p.y+20-t.y)>t.length&&t.last){p.x=t.last.x;p.y=t.last.y;p.vx=0;p.vy=0;}else t.last={x:p.x,y:p.y};}}
export function resetTethers(g){for(const t of g.tethers||[])if(!t.connected){t.held=false;t.last=null;}}
export function drawTethers(c,g){for(const t of g.tethers||[]){if(t.room!==g.rooms?.active)continue;const p=g.player,end=t.connected?{x:t.toX,y:t.toY}:t.held?{x:p.x+14,y:p.y+20}:{x:t.x,y:t.y};c.strokeStyle=t.connected?'#96f2d4':'#d5b787';c.lineWidth=5;c.beginPath();c.moveTo(t.x,t.y);c.quadraticCurveTo((t.x+end.x)/2,Math.min(510,Math.max(t.y,end.y)+55),end.x,end.y);c.stroke();c.fillStyle='#d9e4df';c.fillRect(end.x-8,end.y-6,16,12);c.strokeStyle='#9ac5cb';c.strokeRect(t.toX-13,t.toY-13,26,26);}}
